import React, { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import axios from 'axios';
import { Card, CardContent, Typography, Avatar, Button, Snackbar } from '@mui/material';

function CandidateDetail() {
    const { id } = useParams();
    const [candidat, setCandidat] = useState(null);
    const [error, setError] = useState('');
    const [message, setMessage] = useState('');
    const [openSnackbar, setOpenSnackbar] = useState(false);

    useEffect(() => {
        axios.get(`http://localhost:5000/api/candidats/${id}`)
            .then(response => setCandidat(response.data))
            .catch(err => {
                console.error(err);
                setError("Erreur lors de la récupération du candidat.");
            });
    }, [id]);

    const handleGenerateCode = async () => {
        if (!candidat?.email) {
            setMessage("Email du candidat introuvable.");
            setOpenSnackbar(true);
            return;
        }

        try {
            const response = await axios.post("http://localhost:5000/api/auth/send-otp", { email: candidat.email });
            setMessage(response.data.message || "Code envoyé avec succès !");
        } catch (error) {
            console.error(error);
            setMessage("Erreur lors de l'envoi du code.");
        }
        setOpenSnackbar(true);
    };

    if (error) return <Typography color="error">{error}</Typography>;
    if (!candidat) return <Typography>Chargement...</Typography>;

    return (
        <Card sx={{ maxWidth: 500, margin: 'auto', marginTop: 4, padding: 2 }}>
            <Avatar src={candidat.photo || '/default-avatar.png'} sx={{ width: 100, height: 100, margin: 'auto' }} />
            <CardContent>
                <Typography variant="h5">{candidat.nom} {candidat.prenom}</Typography>
                <Typography>Email: {candidat.email}</Typography>
                <Typography>Téléphone: {candidat.telephone}</Typography>
                <Typography>Parti: {candidat.parti || 'Indépendant'}</Typography>
                <Typography>Slogan: {candidat.slogan}</Typography>

                <Button onClick={handleGenerateCode} variant="contained" color="secondary" sx={{ marginTop: 2 }}>
                    Générer nouveau code
                </Button>

                <Button component={Link} to={`/candidats/${id}/parrainages`} variant="contained" color="primary" sx={{ marginTop: 2, marginLeft: 1 }}>
                    Voir les parrainages reçus
                </Button>
            </CardContent>

            <Snackbar
                open={openSnackbar}
                autoHideDuration={4000}
                onClose={() => setOpenSnackbar(false)}
                message={message}
            />
        </Card>
    );
}

export default CandidateDetail;
